use std::process::Command;

fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = r.max(g.max(b));
    let min = r.min(g.min(b));
    let mut h = 0.0f32;
    let mut s = 0.0f32;
    let l = (max + min) / 2.0;
    if max != min {
        let d = max - min;
        s = if l > 0.5 { d / (2.0 - max - min) } else { d / (max + min) };
        if max == r {
            h = (g - b) / d + if g < b { 6.0 } else { 0.0 };
        } else if max == g {
            h = (b - r) / d + 2.0;
        } else {
            h = (r - g) / d + 4.0;
        }
        h /= 6.0;
    }
    (h, s, l)
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t < 1.0/6.0 { return p + (q - p) * 6.0 * t; }
    if t < 1.0/2.0 { return q; }
    if t < 2.0/3.0 { return p + (q - p) * (2.0/3.0 - t) * 6.0; }
    p
}

fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
    if s == 0.0 {
        return (l, l, l);
    }
    let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
    let p = 2.0 * l - q;
    (
        hue_to_rgb(p, q, h + 1.0/3.0),
        hue_to_rgb(p, q, h),
        hue_to_rgb(p, q, h - 1.0/3.0),
    )
}

fn adjust(r: f32, g: f32, b: f32, factor: f32) -> (f32, f32, f32) {
    let (h, mut s, l) = rgb_to_hsl(r, g, b);
    s = (s * factor).max(0.0).min(1.0);
    hsl_to_rgb(h, s, l)
}

fn parse_f32(s: &str) -> f32 {
    match s {
        "nan" => f32::NAN,
        "-nan" => -f32::NAN,
        "inf" => f32::INFINITY,
        "-inf" => f32::NEG_INFINITY,
        _ => s.parse().unwrap(),
    }
}

fn main() {
    let mut seed: u64 = 0x1234_5678_9abc_def0;
    let mut bad = 0usize;
    let mut max_diff = 0.0f32;
    for _ in 0..300 {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let r = ((seed >> 40) as u32 as f32) / (u32::MAX as f32);
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let g = ((seed >> 40) as u32 as f32) / (u32::MAX as f32);
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let b = ((seed >> 40) as u32 as f32) / (u32::MAX as f32);
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let factor = (((seed >> 40) as u32 as f32) / (u32::MAX as f32)) * 4.0 - 1.0;

        let out = Command::new("./dataset/test9_executable")
            .args([r.to_string(), g.to_string(), b.to_string(), factor.to_string()])
            .output()
            .unwrap();
        let stdout = String::from_utf8(out.stdout).unwrap();
