        let diffs = [
            (got.0 - exp.0).abs(),
            (got.1 - exp.1).abs(),
            (got.2 - exp.2).abs(),
        ];
        let local = diffs.into_iter().fold(0.0, f32::max);
        max_diff = max_diff.max(local);
        if local > 5e-6 {
            bad += 1;
            println!("mismatch r={r} g={g} b={b} f={factor} got={stdout:?} exp={:?}", exp);
            if bad >= 5 { break; }
        }
    }
    println!("bad={bad} max_diff={max_diff}");
}
