use std::process::Command;

fn cpp_max(a: f32, b: f32) -> f32 { if a < b { b } else { a } }
fn cpp_min(a: f32, b: f32) -> f32 { if b < a { b } else { a } }

fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
    let max = cpp_max(cpp_max(r, g), b);
    let min = cpp_min(cpp_min(r, g), b);
    let mut h = 0.0f32;
    let mut s = 0.0f32;
    let l = (max + min) / 2.0;
    if max != min {
        let d = max - min;
        s = if l > 0.5 { d / (2.0 - max - min) } else { d / (max + min) };
        if max == r {
            h = (g - b) / d + if g < b { 6.0 } else { 0.0 };
        } else if max == g {
            h = (b - r) / d + 2.0;
        } else {
            h = (r - g) / d + 4.0;
        }
        h /= 6.0;
    }
    (h, s, l)
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t < 1.0/6.0 { return p + (q - p) * 6.0 * t; }
    if t < 1.0/2.0 { return q; }
    if t < 2.0/3.0 { return p + (q - p) * (2.0/3.0 - t) * 6.0; }
    p
}

fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
    if s == 0.0 { return (l, l, l); }
    let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
    let p = 2.0 * l - q;
    (
        hue_to_rgb(p, q, h + 1.0/3.0),
        hue_to_rgb(p, q, h),
        hue_to_rgb(p, q, h - 1.0/3.0),
    )
}

fn adjust(r: f32, g: f32, b: f32, factor: f32) -> (f32, f32, f32) {
    let (h, s0, l) = rgb_to_hsl(r, g, b);
    let s = cpp_min(cpp_max(s0 * factor, 0.0), 1.0);
    hsl_to_rgb(h, s, l)
}

fn parse_token(s: &str) -> f32 {
    match s {
        "nan" => f32::NAN,
        "-nan" => -f32::NAN,
        "inf" => f32::INFINITY,
        "-inf" => f32::NEG_INFINITY,
        _ => s.parse().unwrap(),
    }
}

fn same(a: f32, b: f32) -> bool {
    if a.is_nan() && b.is_nan() {
        return a.is_sign_negative() == b.is_sign_negative();
    }
    a.to_bits() == b.to_bits()
}

fn main() {
    let cases = [
        ["nan", "0", "0", "1"],
        ["0", "nan", "0", "1"],
        ["0", "0", "nan", "1"],
        ["1", "nan", "0", "1"],
        ["0.2", "0.4", "0.6", "nan"],
        ["0.2", "0.4", "0.6", "inf"],
        ["0.2", "0.4", "0.6", "-inf"],
        ["inf", "0", "0", "1"],
        ["-0", "-0", "-0", "1"],
