        let out = Command::new("./dataset/test9_executable").args(case).output().unwrap();
        let stdout = String::from_utf8(out.stdout).unwrap();
        let parts: Vec<_> = stdout.trim().split(' ').collect();
        let got = (parse_token(parts[0]), parse_token(parts[1]), parse_token(parts[2]));
        let exp = adjust(case[0].parse().unwrap_or_else(|_| if case[0]=="nan" {f32::NAN} else if case[0]=="inf" {f32::INFINITY} else if case[0]=="-inf" {f32::NEG_INFINITY} else if case[0]=="-0" {-0.0} else {panic!()}),
