                         case[2].parse().unwrap_or_else(|_| if case[2]=="nan" {f32::NAN} else if case[2]=="inf" {f32::INFINITY} else if case[2]=="-inf" {f32::NEG_INFINITY} else if case[2]=="-0" {-0.0} else {panic!()}),
                         case[3].parse().unwrap_or_else(|_| if case[3]=="nan" {f32::NAN} else if case[3]=="inf" {f32::INFINITY} else if case[3]=="-inf" {f32::NEG_INFINITY} else if case[3]=="-0" {-0.0} else {panic!()}));
        println!("case={:?} stdout={:?} match={} exp_bits=({:08x},{:08x},{:08x}) got_bits=({:08x},{:08x},{:08x})",
