                 same(got.0, exp.0) && same(got.1, exp.1) && same(got.2, exp.2),
                 exp.0.to_bits(), exp.1.to_bits(), exp.2.to_bits(),
                 got.0.to_bits(), got.1.to_bits(), got.2.to_bits());
    }
}
